def Q(stem, choices, ans, explain, tip, select=None):
    d = {'stem': stem, 'items': [], 'choices': choices, 'explain': explain, 'tip': tip, 'domain': 3}
    if isinstance(ans, list):
        d['answers'] = ans; d['select'] = len(ans)
    else:
        d['answer'] = ans
    return d
